const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// Angiogenesis under a fluorescence microangiogram. A capillary bed branches
// across the field from feeder vessels: trunks divide into ever-finer capillaries
// that meander and anastomose into loops, each drawn as a lumen you can see the
// blood move through -- bright cells stream down every vessel on a pulsatile beat.
// The bed is never finished: distal capillaries perpetually sprout and regress
// (fade in and out on their own slow phases), and each terminal carries a
// migrating tip cell throwing out wiggling filopodia. Flow, pulse and remodelling
// all run on incommensurate rates so nothing converges. Offered as red
// microangiography fluorescence, India-ink perfusion, a metallic corrosion cast,
// or a false-colour Doppler velocity map.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;
const flowAmt = 0.3 + P.flow * 1.4;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 6.1) * 43758.5453; return s - Math.floor(s); };

if (!S.ves || S.seedUsed !== P.seed || S.dU !== (P.density * 100 | 0)) {
  S.seedUsed = P.seed; S.dU = (P.density * 100 | 0);
  S.ves = [];
  let kk = 0; const rk = () => fr(kk++);
  let budget = Math.round(34 + P.density * 40);
  function mkVessel(x, y, ang, rad, depth) {
    if (budget <= 0 || depth > 5 || rad < 0.004) return null;
    budget--;
    const pts = [{ x, y }]; let cx = x, cy = y, a = ang;
    const nseg = 2 + (rk() * 2 | 0), step = (0.06 + rk() * 0.05) * (1.1 - depth * 0.08);
    for (let s2 = 0; s2 < nseg; s2++) { a += (rk() - 0.5) * 0.7; cx += Math.cos(a) * step; cy += Math.sin(a) * step; pts.push({ x: cx, y: cy }); }
    // arclength
    let len = 0; const cum = [0]; for (let s2 = 1; s2 < pts.length; s2++) { len += Math.hypot(pts[s2].x - pts[s2 - 1].x, pts[s2].y - pts[s2 - 1].y); cum.push(len); }
    const v = { pts, cum, len, rad, depth, ang: a, tip: cx, tipy: cy,
      matPhase: rk() * 6.283, matRate: 0.07 + rk() * 0.13 + depth * 0.02,
      swx: rk() * 6.283, swy: rk() * 6.283, swr: 0.02 + rk() * 0.03,
      flowOff: rk(), flowRate: 0.06 + rk() * 0.06, terminal: false, filo: rk() * 6.283 };
    S.ves.push(v);
    // branch
    const nb = depth < 4 ? (rk() < 0.9 ? 2 : 1) : (rk() < 0.5 ? 1 : 0);
    if (nb === 0) { v.terminal = true; return v; }
    let anyChild = false;
    for (let b = 0; b < nb; b++) { const da = (b === 0 ? -1 : 1) * (0.3 + rk() * 0.6); const c = mkVessel(cx, cy, a + da, rad * (0.66 + rk() * 0.12), depth + 1); if (c) anyChild = true; }
    if (!anyChild) v.terminal = true;
    return v;
  }
  const nRoot = 2 + (P.density * 2 | 0);
  for (let r = 0; r < nRoot; r++) { const edge = fr(r * 9 + 1); const rx = edge < 0.5 ? 0.02 : 0.98, ry = 0.15 + fr(r * 7 + 2) * 0.7; const a0 = edge < 0.5 ? (fr(r * 5 + 3) - 0.5) * 1.2 : Math.PI + (fr(r * 5 + 3) - 0.5) * 1.2; mkVessel(rx, ry, a0, 0.02 + fr(r * 11 + 4) * 0.012, 0); }
}

// helper: point + tangent at arclength s along a vessel
function posAt(v, s) {
  s = Math.max(0, Math.min(v.len, s));
  let seg = 1; while (seg < v.cum.length && v.cum[seg] < s) seg++;
  if (seg >= v.pts.length) seg = v.pts.length - 1;
  const s0 = v.cum[seg - 1], s1 = v.cum[seg], f = s1 > s0 ? (s - s0) / (s1 - s0) : 0;
  const a = v.pts[seg - 1], b = v.pts[seg];
  return { x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f, ang: Math.atan2(b.y - a.y, b.x - a.x) };
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.3 + A.rms * 0.35;
const pulse = 0.7 + 0.3 * Math.sin(t * 2.0 * sp) + K.pulse * 0.3 + A.bass * 0.3;   // heartbeat

let bgH, bgS, bgB, mode;
if (style === 'ink') { bgH = 32; bgS = 16; bgB = 70; mode = 'ink'; }
else if (style === 'cast') { bgH = 220; bgS = 30; bgB = 8; mode = 'cast'; }
else if (style === 'thermal') { bgH = 240; bgS = 40; bgB = 10; mode = 'thermal'; }
else { bgH = 348; bgS = 55; bgB = 8; mode = 'fluor'; }
const pale = (mode === 'ink');

const scl = u * P.scale;
// slow whole-bed vasomotion / stage drift on incommensurate rates -> broad motion
const driftX = Math.sin(t * 0.09 * sp) * u * 0.04 + Math.sin(t * 0.021 * sp + 1.3) * u * 0.022;
const driftY = Math.cos(t * 0.073 * sp) * u * 0.04 + Math.sin(t * 0.017 * sp + 0.6) * u * 0.022;
const ox = (P.x - 0.5) * width * 0.3 + driftX, oy = (P.y - 0.5) * height * 0.3 + driftY;
function X(nx) { return nx * scl + (width - scl) * 0.5 + ox; }
function Y(ny) { return ny * scl + (height - scl) * 0.5 + oy; }

push();
noStroke(); rectMode(CORNER);
fill(bgH, bgS, bgB); rect(0, 0, width, height);
// soft tissue / perfusion haze (broad low-alpha lift)
for (let ri = 6; ri >= 1; ri--) { const rr = u * (0.28 + ri * 0.13); if (pale) fill(bgH, bgS * 0.6, bgB - (7 - ri) * 1.6, 22); else fill((bgH + 8) % 360, bgS * 0.75, Math.min(52, bgB + (7 - ri) * 4.4), 22); ellipse(width * 0.5, height * 0.5, rr * 2.1, rr * 1.9); }
// faint diffuse tissue autofluorescence field to seat the bed (broad luminance lift)
if (!pale) { for (let b = 0; b < 40; b++) { const bx = fr(b * 3 + 700), by = fr(b * 5 + 701); fill((bgH + 6) % 360, bgS * 0.6, bgB + 6 + fr(b * 2) * 8, 8); ellipse(bx * width, by * height, u * (0.12 + fr(b * 7) * 0.16), u * (0.12 + fr(b * 6) * 0.16)); } }

strokeCap(ROUND); strokeJoin(ROUND);

if (mode === 'fluor' || mode === 'thermal') blendMode(ADD);

for (let vi = 0; vi < S.ves.length; vi++) {
  const v = S.ves[vi];
  // remodelling: distal vessels sprout/regress; trunks stay
  const matRaw = 0.5 + 0.5 * Math.sin(t * v.matRate * sp + v.matPhase);
  const mat = v.depth <= 1 ? (0.85 + 0.15 * matRaw) : (0.18 + 0.82 * matRaw);
  const radMod = 1 + 0.2 * Math.sin(t * (0.12 + v.swr) * sp + v.swx);   // slow vasomotion (width breathing)
  const rad = v.rad * scl * radMod;
  const hue = (P.hue + (mode === 'thermal' ? 0 : v.depth * 4)) % 360;

  // ---- lumen (tapered tube) ----
  for (let s2 = 1; s2 < v.pts.length; s2++) {
    const a = v.pts[s2 - 1], b = v.pts[s2];
    const rr = rad * (1 - (v.cum[s2] / (v.len + 1e-4)) * 0.4);
    let sat, br, al;
    if (mode === 'ink') { sat = 20; br = 16; al = 82 * mat; }
    else if (mode === 'cast') { const sh = 0.5 + 0.5 * Math.sin(a.x * 12 + a.y * 9); sat = 26; br = 30 + sh * 40; al = 90 * mat; }
    else if (mode === 'thermal') { sat = 55; br = 30 * glow; al = 60 * mat; }
    else { sat = 60; br = Math.min(100, 34 * glow); al = 55 * mat; }
    stroke(mode === 'cast' ? 40 : hue, sat, br, al); strokeWeight(Math.max(0.7, rr * 2));
    line(X(a.x), Y(a.y), X(b.x), Y(b.y));
    // vessel wall highlight for glow styles
    if (mode === 'fluor') { stroke(hue, sat - 20, Math.min(100, br * 1.8), al * 0.7); strokeWeight(Math.max(0.4, rr * 0.7)); line(X(a.x), Y(a.y), X(b.x), Y(b.y)); }
  }

  // ---- flowing blood cells along the lumen ----
  noStroke();
  const ncell = Math.max(1, Math.round(v.len * 22 * (0.5 + P.density * 0.8)));
  const gap = v.len / ncell;
  const adv = (v.flowOff + t * v.flowRate * flowAmt * pulse) ;
  for (let c = 0; c < ncell; c++) {
    const s = ((adv + c * (1 / ncell)) % 1) * v.len;
    const pt = posAt(v, s);
    const cellR = rad * (1 - (s / (v.len + 1e-4)) * 0.4) * 1.5;
    if (cellR < 0.8) continue;
    let ch, cs, cb, ca;
    if (mode === 'ink') { ch = 32; cs = 10; cb = 40; ca = 55 * mat; }
    else if (mode === 'cast') { ch = 44; cs = 20; cb = 78; ca = 60 * mat; }
    else if (mode === 'thermal') { const vel = 0.5 + 0.5 * Math.sin(s * 6 + t * 3 * sp); ch = 240 - vel * 240; cs = 75; cb = Math.min(100, (45 + vel * 45) * glow); ca = 80 * mat; }
    else { ch = (P.hue + 12) % 360; cs = 75; cb = Math.min(100, 66 * glow); ca = 82 * mat; }
    push(); translate(pt.x, pt.y); rotate(pt.ang); fill(ch, cs, cb, ca); ellipse(0, 0, cellR * 2.2, cellR * 1.3); pop();
  }

  // ---- migrating tip cell + filopodia on terminals ----
  if (v.terminal && mode !== 'ink') {
    const ext = 1 + 0.3 * Math.sin(t * (v.matRate * 3) * sp + v.matPhase);
    const tx = X(v.tip), ty = Y(v.tipy);
    noStroke(); fill(hue, 60, Math.min(100, 60 * glow), 60 * mat); ellipse(tx, ty, rad * 3 * ext, rad * 3 * ext);
    stroke(hue, 55, Math.min(100, 55 * glow), 55 * mat); strokeWeight(Math.max(0.4, rad * 0.5));
    for (let f = 0; f < 5; f++) { const fa = v.ang + (f - 2) * 0.5 + Math.sin(t * 1.5 * sp + v.filo + f) * 0.4; const fl = rad * (3 + 3 * Math.abs(Math.sin(t * 1.2 + f))); line(tx, ty, tx + Math.cos(fa) * fl, ty + Math.sin(fa) * fl); }
